const sum = (amounts: number[]): number => amounts.reduce((a, b) => a + b, 0);

/**
 * Groups items by type so that alike items are priced together. Main items are
 * kept in groups of one, since only components are ever bundled.
 */
const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

/**
 * Components of one kind are bundled into building blocks of 3, each charged at
 * the special block rate; leftovers are charged individually. Main items are
 * always charged individually.
 */
const groupBasePremium = (type: string, count: number): number => {
  const blocks = isComponent(type) ? Math.floor(count / BUILDING_BLOCK_SIZE) : 0;
  const singles = count - blocks * BUILDING_BLOCK_SIZE;
  return blocks * BUILDING_BLOCK_BASE_PREMIUM + singles * BASE_PREMIUM[type];
};

const totalBasePremiumOf = (items: Item[]): number =>
  sum([...countByType(items)].map(([type, count]) => groupBasePremium(type, count)));

